CREATE VIEW dq_external_id_conflicts AS (SELECT 'IGDB' AS id_type, CAST(igdb_id AS VARCHAR) AS external_id, count(DISTINCT game_title) AS title_count FROM std_inventory_curated WHERE (igdb_id IS NOT NULL) GROUP BY igdb_id HAVING (count(DISTINCT game_title) > 1)) UNION ALL (SELECT 'OPENCRITIC' AS id_type, CAST(opencritic_id AS VARCHAR) AS external_id, count(DISTINCT game_title) AS title_count FROM std_inventory_curated WHERE (opencritic_id IS NOT NULL) GROUP BY opencritic_id HAVING (count(DISTINCT game_title) > 1));
